[Form]
public class AVAPurchAgreementLineFrm extends FormRun
{

    InventTable     sourceInventTable;
    AVAPurchAgreementLineTmp agreementLineOpenOrderTmp;
}

/// <summary>
/// designed from AVA
/// </summary>
public void updateFollowUpFields()
{
    #AgreementsRemains
    container fulfillmentValues;

    // Query all fulfillment values at once...
    fulfillmentValues += AgreementLine::calculateFulfillmentForLine(AgreementLine);

    // Distributing them among fulfillment fields.
    agreementDelivered.realValue(        conPeek(fulfillmentValues, #DeliveredNotInvoicedIndex));
    agreementInvoiced.realValue(         conPeek(fulfillmentValues, #InvoicedIndex));
    agreementRemainingRelease.realValue( conPeek(fulfillmentValues, #RemainingIndex));
    agreementReleased.realValue(         conPeek(fulfillmentValues, #ReleasedNotInvoicedNorDeliveredIndex));
}

/// <summary>
///    Method to check if project is in valid stage to release the purchase agreement.
/// </summary>
/// <param name="_agreementHeader">
///    A table buffer that contains the current Agreement Header table values.
/// </param>
/// <returns>
///    true if user has set project parameters to allow creating item tasks for the given project stage
///    or when purchase agreement is not assigned to any project, false otherwise.
/// </returns>
public boolean isProjectStageValidToCreateItemTask(AgreementHeader _agreementHeader)
{
    ProjId projId = _agreementHeader.agreementHeaderDefault().Project;
    if (projId)
    {
        return ProjTable::isCreateItemTaskRuleDefined(projId);
    }
    else
    {
        return true;
    }
}

/// <summary>
/// Gets the direct invoice state of the selected purchase agreement in a list page.
/// </summary>
/// <param name="_purchAgreementHeader">
/// The active record in the <c>PurchAgreementHeader</c> table.
/// </param>
/// <returns>
/// A Boolean value that indicates whether direct invoice is enabled on the classification of selected
/// purchase orders in the list page.
/// </returns>
/// <remarks>
/// This is public sector code.
/// </remarks>
public boolean getDirectInvoiceEnabledState(PurchAgreementHeader _purchAgreementHeader)
{
    return AgreementClassification::find(_purchAgreementHeader.AgreementClassification).DirectInvoiceEnable_PSN;
}

/// <summary>
/// returns a boolean value depending on forms specific values
/// </summary>
/// <returns>boolean</returns>
public boolean enableCallOff()
{
    FormDesign design = this.design();
    AgreementHeader agreementHeaderLoc = AgreementLine.agreementHeader();
    container relatedObjectsExistanceFlags = agreementHeaderLoc.relatedObjectExistanceFlags();

    boolean canRelease                              = conPeek(relatedObjectsExistanceFlags, AgreementHeader::posCanReleaseAgreement()) && this.isProjectStageValidToCreateItemTask(agreementHeaderLoc);
    boolean enableControl                           = !this.getDirectInvoiceEnabledState(agreementHeaderLoc);
    boolean frenchContextEnabled;
    boolean canAddLinesToAgreement  = true;
    boolean canCallOfRelease        = true;

    if (isConfigurationkeyEnabled(configurationKeyNum(PublicSector)))
    {    
        frenchContextEnabled = PublicSectorUtils::isFrenchRegulatoryEnabled();

        if (frenchContextEnabled)
        {
            canAddLinesToAgreement = agreementHeaderLoc.canAddLinesToAgreement();
        }

        canCallOfRelease = enableControl && canRelease && canAddLinesToAgreement;
    }
    else
    {
        canCallOfRelease = canRelease;
    }

    return canCallOfRelease && !agreementLine.AVAStopped;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>agreementLineOpenOrderTmp</returns>
public AVAPurchAgreementLineTmp initAgreementLineOpenOrderTmp()
{
    if(element.args().dataset() == tableNum(InventTable))
    {
        sourceInventTable = element.args().record();
    }

    //this.queryBuildDataSource().addRange(fieldNum(PurchAgreementHeader,AgreementState)).value(SysQuery::valueNot(AgreementState::Closed));
    PurchAgreementHeader locPurchAgreementHeader;
    AgreementLine locAgreementLine;
    ttsbegin;
    while select locAgreementLine
        where !locAgreementLine.IsDeleted
        && (locAgreementLine.ItemId == sourceInventTable.ItemId || !sourceInventTable)
        exists join locPurchAgreementHeader
        where locPurchAgreementHeader.RecId == locAgreementLine.Agreement
        && !locPurchAgreementHeader.IsDeleted
        && (locPurchAgreementHeader.AgreementState != AgreementState::Closed || !sourceInventTable)
    {
        agreementLineOpenOrderTmp.clear();
        agreementLineOpenOrderTmp.initFromAgreementLine(locAgreementLine);
        agreementLineOpenOrderTmp.insert();
    }
    ttscommit;

    return agreementLineOpenOrderTmp;
}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    super();
    avaPurchAgreementLineTmp.linkPhysicalTableInstance(this.initAgreementLineOpenOrderTmp());

}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    super();
    if(sourceInventTable)
    {
        this.queryBuildDataSource().addRange(fieldNum(AgreementLine,ItemId)).value(sourceInventTable.ItemId);
    }
    this.queryBuildDataSource().addRange(fieldNum(AgreementLine, IsDeleted)).value(SysQuery::value(NoYes::No));
 //   purchAgreementHeader_ds.query().dataSourceTable(tableNum(PurchAgreementHeader)).addRange(fieldnum(PurchAgreementHeader,AgreementState)).value(enum2Str(AgreementState::Effective));
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = super();
    AVACallOffReleaseItem.enabled(element.enableCallOff());

 //   element.updateFollowUpFields();

    return ret;
}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    super();
    if(sourceInventTable.RecId)
    {
        this.queryBuildDataSource().addRange(fieldNum(PurchAgreementHeader,AgreementState)).value(SysQuery::valueNot(AgreementState::Closed));
    }
    this.queryBuildDataSource().addRange(fieldNum(PurchAgreementHeader, IsDeleted)).value(SysQuery::value(NoYes::No));
}

/// <summary>
/// designed from AVA
/// </summary>
public void jumpRef()
{
    //super();
    PurchAgreementHeader  locPurchAgreementHeader;
    MenuFunction    menuFunction;
    Args            args = new Args();

    locPurchAgreementHeader = PurchAgreementHeader::find(PurchAgreementHeader.RecId);

    if (!locPurchAgreementHeader)
    {
        return;
    }

    args.record(locPurchAgreementHeader);

    menuFunction = new MenuFunction(menuitemDisplayStr(PurchAgreement), MenuItemType::Display);
    menuFunction.openMode(OpenMode::View);
    menuFunction.formViewOption(FormViewOption::Details);
    menuFunction.run(args);
}

